# ============ Top-level dispatch ============

VALID_SUBCOMMANDS = ["check", "dump", "explain", "fix", "help", "list", "single"]

def print_help_for(sub):
    if sub == "check":
        out_write(CHECK_HELP)
    elif sub == "fix":
        out_write(FIX_HELP)
    elif sub == "list":
        out_write(LIST_HELP)
    elif sub == "explain":
        out_write(EXPLAIN_HELP)
    elif sub == "dump":
        out_write(DUMP_HELP)
    elif sub == "single":
        out_write(SINGLE_HELP)
    elif sub == "help":
        # help help => HELP_HELP2
        out_write(HELP_HELP2)
    else:
        # should not happen
        pass

def handle_help_subcommand(args):
    # args after 'help', e.g. [] or ['check'] or ['check','fix'] or ['--help']
    # No flags, all are subcommand names
    if len(args) == 0:
        out_write(MAIN_HELP)
        return 0
