# ============ Subcommand parsers ============

# Known flags for check/fix/single
# For check: -c/--config (value), -h/--help, -i/--ignore (multi-value), -o/--format (value), -s/--stdin, -u/--unrestricted
# For fix: -c/--config, -d/--dry-run, -h/--help, -i/--ignore, -s/--stdin, -u/--unrestricted
# For single: -c/--config, -d/--dry-run, -h/--help, -p/--position (value, required), -s/--stdin
# For list/dump: -h/--help only
# For explain: -h/--help + required TARGET

def is_known_long(flag_name, subcmd):
    # flag_name without --, e.g. "config", "ignore", "format", "stdin", "unrestricted", "dry-run", "position", "help"
    if subcmd == "check":
        return flag_name in ("config", "help", "ignore", "format", "stdin", "unrestricted")
    elif subcmd == "fix":
        return flag_name in ("config", "dry-run", "help", "ignore", "stdin", "unrestricted")
    elif subcmd == "single":
        return flag_name in ("config", "dry-run", "help", "position", "stdin")
    elif subcmd in ("list", "dump"):
        return flag_name in ("help",)
    elif subcmd == "explain":
        return flag_name in ("help",)
    return False

def is_known_short(ch, subcmd):
    if subcmd == "check":
        return ch in ("c", "h", "i", "o", "s", "u")
    elif subcmd == "fix":
        return ch in ("c", "d", "h", "i", "s", "u")
    elif subcmd == "single":
        return ch in ("c", "d", "h", "p", "s")
    elif subcmd in ("list", "dump", "explain"):
        return ch in ("h",)
    return False

def short_takes_value(ch, subcmd):
    if subcmd == "check":
        return ch in ("c", "i", "o")
    elif subcmd == "fix":
        return ch in ("c", "i")
    elif subcmd == "single":
        return ch in ("c", "p")
    return False

def long_takes_value(name, subcmd):
    if subcmd == "check":
        return name in ("config", "ignore", "format")
    elif subcmd == "fix":
        return name in ("config", "ignore")
    elif subcmd == "single":
        return name in ("config", "position")
    return False

def long_is_multi(name):
    return name == "ignore"

def short_is_multi(ch):
    return ch == "i"

PYEOF
echo done
"}

