{"command":"cat >> /workspace/statix.py <<'ENDOFFILE'

CHECK_SPEC = {
    "config": ("c", True, False, "--config <CONF_PATH>"),
    "help": ("h", False, False, None),
    "ignore": ("i", True, True, "--ignore <IGNORE>..."),
    "format": ("o", True, False, "--format <FORMAT>"),
    "stdin": ("s", False, False, None),
    "unrestricted": ("u", False, False, None),
}
FIX_SPEC = {
    "config": ("c", True, False, "--config <CONF_PATH>"),
    "dry-run": ("d", False, False, None),
    "help": ("h", False, False, None),
    "ignore": ("i", True, True, "--ignore <IGNORE>..."),
    "stdin": ("s", False, False, None),
    "unrestricted": ("u", False, False, None),
}
SINGLE_SPEC = {
    "config": ("c", True, False, "--config <CONF_PATH>"),
    "dry-run": ("d", False, False, None),
    "help": ("h", False, False, None),
    "position": ("p", True, False, "--position <POSITION>"),
    "stdin": ("s", False, False, None),
}
LIST_SPEC = {"help": ("h", False, False, None)}
DUMP_SPEC = {"help": ("h", False, False, None)}
EXPLAIN_SPEC = {"help": ("h", False, False, None)}

def build_short_map(spec):
    m={}
    for long,(short,takes,multi,specstr) in spec.items():
        m[short]=long
    return m

def parse_subcommand(sub, argv, usage, usage_line, spec, help_text, max_pos, min_pos=0, required_opts=[]):
    short_map=build_short_map(spec)
    values={}
    seen=set()
    flag_seen=set()
    for long,(short,takes,multi,specstr) in spec.items():
        if not takes:
            values[long]=False
        else:
            values[long]=None
    positionals=[]
    i=0
    n=len(argv)
    after_dd=False
    def check_nxt_is_flag(nxt):
        # returns (is_flag, is_known, flag_desc_for_error)
        # nxt starts with - and != -
        if nxt.startswith("--"):
            nn=nxt[2:].split("=",1)[0]
            if nn in spec:
                return (True, True, None)
            else:
                return (True, False, "--"+nn)
        else:
            if len(nxt)>=2:
                ch=nxt[1]
                if ch in short_map:
                    return (True, True, None)
                else:
                    return (True, False, "-"+ch)
            return (True, False, nxt)
    while i<n:
        arg=argv[i]
        if after_dd:
            positionals.append(arg)
            if len(positionals)>max_pos:
                cli_unknown(arg, usage)
                sys.exit(2)
            i+=1
            continue
        if arg=="--":
            after_dd=True
            i+=1
            continue
        if arg=="-":
            positionals.append(arg)
            if len(positionals)>max_pos:
                cli_unknown(arg, usage)
                sys.exit(2)
            i+=1
            continue
        if arg.startswith("--"):
            if "=" in arg:
                name,val=arg[2:].split("=",1)
                if name not in spec:
                    cli_unknown("--"+name, usage)
                    sys.exit(2)
                short,takes,multi,specstr=spec[name]
                if not takes:
                    cli_unexpected_value("--"+name, "="+val, usage_line)
                    sys.exit(2)
                if name in seen:
                    cli_multiple(specstr, usage)
                    sys.exit(2)
                seen.add(name)
                if multi:
                    values[name]=[val]
                else:
                    values[name]=val
                i+=1
                continue
            else:
                name=arg[2:]
                if name not in spec:
                    cli_unknown(arg, usage)
                    sys.exit(2)
                short,takes,multi,specstr=spec[name]
                if name=="help":
                    out_write(help_text)
                    sys.exit(0)
                if not takes:
                    values[name]=True
                    flag_seen.add(name)
                    i+=1
                    continue
                if name in seen:
                    cli_multiple(specstr, usage)
                    sys.exit(2)
                if i+1>=n:
                    cli_missing_value(specstr, usage)
                    sys.exit(2)
                nxt=argv[i+1]
                if nxt=="--":
                    cli_missing_value(specstr, usage)
                    sys.exit(2)
                if nxt.startswith("-") and nxt!="-":
                    isf,isk,desc=check_nxt_is_flag(nxt)
                    if isk:
                        cli_missing_value(specstr, usage)
                        sys.exit(2)
                    else:
                        cli_unknown(desc, usage)
                        sys.exit(2)
                seen.add(name)
                if multi:
                    lst=[]
                    j=i+1
                    while j<n:
                        cand=argv[j]
                        if cand=="--":
                            break
                        if cand.startswith("-") and cand!="-":
                            break
                        lst.append(cand)
                        j+=1
                    values[name]=lst
                    i=j
                    continue
                else:
                    values[name]=nxt
                    i+=2
                    continue
        elif arg.startswith("-"):
            pos=1
            L=len(arg)
            broken_by_value=False
            while pos<L:
                ch=arg[pos]
                if ch not in short_map:
                    cli_unknown("-"+ch, usage)
                    sys.exit(2)
                long=short_map[ch]
                short,takes,multi,specstr=spec[long]
                if long=="help":
                    out_write(help_text)
                    sys.exit(0)
                if not takes:
                    values[long]=True
                    flag_seen.add(long)
                    pos+=1
                    continue
                if long in seen:
                    cli_multiple(specstr, usage)
                    sys.exit(2)
                if pos+1<L:
                    rest=arg[pos+1:]
                    seen.add(long)
                    if multi:
                        values[long]=[rest]
                    else:
                        values[long]=rest
                    pos=L
                    broken_by_value=True
                    break
                else:
                    if i+1>=n:
                        cli_missing_value(specstr, usage)
                        sys.exit(2)
                    nxt=argv[i+1]
                    if nxt=="--":
                        cli_missing_value(specstr, usage)
                        sys.exit(2)
                    if nxt.startswith("-") and nxt!="-":
                        isf,isk,desc=check_nxt_is_flag(nxt)
                        if isk:
                            cli_missing_value(specstr, usage)
                            sys.exit(2)
                        else:
                            cli_unknown(desc, usage)
                            sys.exit(2)
                    seen.add(long)
                    if multi:
                        lst=[]
                        j=i+1
                        while j<n:
                            cand=argv[j]
                            if cand=="--":
                                break
                            if cand.startswith("-") and cand!="-":
                                break
                            lst.append(cand)
                            j+=1
                        values[long]=lst
                        i=j-1
                        pos=L
                        broken_by_value=True
                        break
                    else:
                        values[long]=nxt
                        i+=1
                        pos=L
                        broken_by_value=True
                        break
            i+=1
            continue
        else:
            positionals.append(arg)
            if len(positionals)>max_pos:
                cli_unknown(arg, usage)
                sys.exit(2)
            i+=1
            continue
    if len(positionals)<min_pos:
        if sub=="explain":
            cli_missing_required(["<TARGET>"], usage)
            sys.exit(2)
    for req in required_opts:
        if req not in seen:
            _,_,_,specstr=spec[req]
            use_usage=usage
            if sub=="single" and req=="position":
                has_dry=("dry-run" in flag_seen)
                has_stdin=("stdin" in flag_seen)
                has_target=(len(positionals)>0)
                if not has_dry and not has_stdin and not has_target:
                    use_usage=USAGE_SINGLE
                else:
                    s="executable single --position <POSITION>"
                    if has_dry:
                        s+=" --dry-run"
                    if has_stdin:
                        s+=" --stdin"
                    if has_target:
                        s+=" <TARGET>"
                    use_usage="USAGE:\n    "+s
            cli_missing_required([specstr], use_usage)
            sys.exit(2)
    return values, positionals, flag_seen, seen

ENDOFFILE
echo done
"}

