            continue
        # Also check overlapping with already selected? Since sorted, just check last_end.
        non_over.append((s,e,r))
        last_end=e
    if not non_over:
        return (text, False)
    # Apply from end to start to preserve offsets? Or from start with offset adjustment? Easiest: apply from end backwards.
    new_text=text
    for s,e,r in reversed(non_over):
        new_text=new_text[:s]+r+new_text[e:]
    changed=(new_text!=text)
    return (new_text, changed)

